'use strict';
// Extracted by the existing isolated CDP runner. Synthetic data only, in a fresh CI browser.
const harness=String.raw`
(async()=>{
 const results=[];
 const assert=(ok,name)=>{if(!ok)throw Error(name);results.push({name,passed:true});};
 const sleep=ms=>new Promise(r=>setTimeout(r,ms));
 const frame=document.createElement('iframe');frame.style.cssText='width:100%;max-width:390px;height:1000px;border:0';document.body.append(frame);
 let w;const doc=()=>frame.contentDocument;
 const until=async fn=>{for(let i=0;i<200;i++){if(fn())return;await sleep(25);}throw Error('Timed out: '+(doc().querySelector('#toast')?.textContent||'no toast'));};
 const navigate=(extra='')=>new Promise(resolve=>{frame.onload=()=>{w=frame.contentWindow;resolve();};frame.src='/quality-system-prototype/sustainability/departments.html?ci='+Date.now()+extra;});
 const click=s=>{const e=doc().querySelector(s);if(!e)throw Error('Missing control '+s);e.click();};
 const change=(s,value)=>{const e=doc().querySelector(s);if(!e)throw Error('Missing input '+s);e.value=value;e.dispatchEvent(new w.Event('change',{bubbles:true}));};
 const fill=(s,value)=>{const e=doc().querySelector(s);e.value=value;e.dispatchEvent(new w.Event('input',{bubbles:true}));};
 const key='tobruk-continuity-departments-v1';
 const records=()=>JSON.parse(w.localStorage.getItem(key)).records;
 const current=()=>records().find(r=>r.id===new URLSearchParams(w.location.hash.slice(1)).get('record'));
 try{
  localStorage.clear();await navigate();await until(()=>doc().querySelector('.unit'));
  assert(doc().querySelectorAll('.unit').length===20,'All 20 department cards rendered');
  assert(w.ContinuityData.units.every(u=>u.items.length===5),'Exactly five items in every template');
  assert(doc().documentElement.dir==='rtl','Arabic RTL');
  localStorage.setItem('tobruk-sustainability-v04','legacy-synthetic-sentinel');
  click('[data-command="unit"][data-id="10"]');
  assert(doc().querySelectorAll('[data-check]').length===5,'Examinations unit has five inputs');
  assert(current().answers.every(a=>a===''),'Initial answers are unset');
  click('#q-0');change('#s-1','needs');change('#s-2','unknown');change('#s-3','na');
  fill('#review-note','Synthetic continuity QA note');
  const firstId=current().id;
  click('[data-command="finish"]');
  assert(!!current().closedAt,'Finish closes the same record');
  assert(doc().querySelector('.summary-title').textContent.includes('نقاط محددة'),'Summary shows needs, not a score');
  assert(doc().querySelectorAll('.summary-row').length===5,'Summary retains all five states');
  click('[data-command="new-review"]');
  assert(current().id!==firstId&&current().previous===firstId,'New review is a separate linked record');
  assert(doc().querySelectorAll('[data-check]:checked').length===0,'All new-review checkboxes are unchecked');
  assert([...doc().querySelectorAll('[data-status]')].every(e=>e.value===''),'All new-review dropdowns are unset');
  assert(doc().querySelector('#review-note').value==='','New-review note is blank');
  assert(records().find(r=>r.id===firstId).answers[1]==='needs','Earlier answers remain unchanged');
  await navigate('&unit=10');await until(()=>doc().querySelector('[data-check]'));
  assert(current().previous===firstId&&current().answers.every(a=>a===''),'Actual reload retains the blank new draft');
  click('#nav-history');
  assert(doc().querySelectorAll('.record').length===2,'Two records exist after new review');
  click('[data-command="record"][data-id="'+firstId+'"]');
  assert(doc().querySelector('.note-block').textContent==='Synthetic continuity QA note','Earlier note is retrievable after actual reload');
  await navigate('#record='+firstId);await until(()=>doc().querySelector('.summary-title'));
  assert(current().id===firstId&&!!current().closedAt,'Direct saved-record reload works');
  click('[data-command="edit"]');change('#s-0','na');change('#s-1','na');change('#s-2','na');change('#s-3','na');change('#s-4','na');
  click('[data-command="finish"]');assert(doc().querySelector('.summary-title').textContent.includes('لا تنطبق'),'All N/A is not counted as success');
  click('[data-command="edit"]');change('#review-scope','inactive');click('[data-command="finish"]');
  assert(doc().querySelector('.summary-title').textContent.includes('غير مفعّلة'),'Inactive department is not failed');
  click('[data-command="edit"]');change('#review-scope','active');change('#s-0','');click('[data-command="finish"]');
  assert(doc().querySelector('.summary-title').textContent.includes('لم يكتمل'),'Blank answer stays incomplete rather than negative');
  const captured=[];const oldCreate=w.URL.createObjectURL.bind(w.URL);
  w.URL.createObjectURL=blob=>{captured.push(blob);return oldCreate(blob);};w.HTMLAnchorElement.prototype.click=function(){};
  click('[data-command="export-one"]');assert(captured.length===1,'Export creates one downloadable package');
  const pack=JSON.parse(await captured[0].text());assert(pack.records.length===1&&pack.format==='tobruk-continuity-departments','Export has the new versioned format');
  click('#nav-history');const count=records().length;
  const transfer=new w.DataTransfer();transfer.items.add(new w.File([JSON.stringify(pack)],'test.json',{type:'application/json'}));
  const inp=doc().querySelector('#import-file');inp.files=transfer.files;inp.dispatchEvent(new w.Event('change',{bubbles:true}));
  await until(()=>doc().querySelector('#toast').textContent.includes('لم نكررها'));
  assert(records().length===count,'Duplicate import does not create duplicates');
  click('#nav-home');click('[data-command="unit"][data-id="16"]');
  assert(doc().querySelector('.checklabel').textContent.includes('سجل الطلبة'),'Registrar card has distinct content');
  fill('#review-note','<img src=x onerror=alert(1)>');click('[data-command="finish"]');
  assert(doc().querySelector('.note-block img')===null,'Imported or entered notes are rendered as text');
  assert(w.localStorage.getItem('tobruk-sustainability-v04')==='legacy-synthetic-sentinel','Legacy records are untouched');
  assert(doc().documentElement.scrollWidth<=w.innerWidth+1,'No horizontal overflow at mobile width');
  document.body.dataset.qa='passed';document.getElementById('qa-result').textContent=JSON.stringify({passed:results.length,environment:'Real Chromium browser and localStorage on an isolated CI origin',results},null,2);
 }catch(e){document.body.dataset.qa='failed';document.getElementById('qa-result').textContent=JSON.stringify({error:e.message,passed:results.length,results},null,2);}
})();
`;
const mime={};
